#!/usr/bin/env python3
"""Reject certificate-package sources or replay artifacts in the monorepo."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import subprocess
import tomllib
from pathlib import Path


LEAN_ROOT = Path(__file__).resolve().parents[1]
REPO_ROOT = LEAN_ROOT.parent
CONFIG = LEAN_ROOT / "trust" / "certificate-packages.toml"
IMPORT_RE = re.compile(r"^import\s+([A-Za-z0-9_'.]+)\s*$", re.MULTILINE)
# A generated source says so about itself.  Ordinary mathematical prose says "the
# subgroup generated by ...", so the naming of a generator is what discriminates:
# either an explicit do-not-edit marker, or "generated by" followed by a script name
# in backticks.  The backticked name must look like one: a path separator or an
# extension dot.  Without that requirement the rule also matches "the principal ideal
# generated by `a`", which is what put two hand-written base modules on the
# unclassified list.
BANNER_RE = re.compile(
    r"DO NOT EDIT|automatically generated|generated by[ \t]+`[^`]*[./][^`]*`",
    re.IGNORECASE,
)
# The same banner, read for the generator it names rather than for the fact that it
# names one.  A generated leaf is payload, and so is the program that produced it, but
# the generator is not a Lean file and usually does not live beside the family it
# writes: in this repository every resident generator sits under `notes/`, which the
# scan roots below never reach.
GENERATOR_RE = re.compile(
    r"generated by[ \t]+`([^`]*[./][^`]*?)`", re.IGNORECASE
)


def tracked_paths(repo_root: Path) -> list[Path]:
    result = subprocess.run(
        ["git", "ls-files", "--cached", "--others", "--exclude-standard", "--", "lean", "papers"],
        cwd=repo_root,
        check=True,
        text=True,
        capture_output=True,
    )
    return [repo_root / line for line in result.stdout.splitlines()]


def module_name(lean_root: Path, path: Path) -> str | None:
    try:
        relative = path.relative_to(lean_root)
    except ValueError:
        return None
    if path.suffix != ".lean":
        return None
    return ".".join(relative.with_suffix("").parts)


def violations(repo_root: Path, lean_root: Path, config: Path) -> list[str]:
    with config.open("rb") as handle:
        document = tomllib.load(handle)
    problems: list[str] = []
    paths = tracked_paths(repo_root)
    for package in document.get("package", []):
        prefixes = tuple(package["owned_module_prefixes"])
        forbidden_names = set(package["forbidden_artifact_basenames"])
        for path in paths:
            relative = path.relative_to(repo_root)
            if path.name in forbidden_names:
                problems.append(f"{relative}: certificate artifact belongs to {package['name']}")
            module = module_name(lean_root, path)
            if module is not None and module.startswith(prefixes):
                problems.append(f"{relative}: module belongs to {package['name']}")
            if path.suffix == ".lean" and path.is_file():
                for imported in IMPORT_RE.findall(path.read_text(encoding="utf-8")):
                    if imported.startswith(prefixes):
                        problems.append(
                            f"{relative}: imports {imported}, owned by {package['name']}"
                        )
    return sorted(set(problems))


def undeclared_generated_families(
    repo_root: Path, lean_root: Path, config: Path
) -> list[str]:
    """Reject a generated family belonging to no package and to no declared pending family.

    The prefix and basename rules above recognize only what a package has already
    declared, so they detect a family coming back and never a family arriving.  A
    generated source identifies itself in its own banner, which is what this rule
    reads instead.  Families still resident in the monorepo are declared as pending
    with the package that will own them; that declaration is empty exactly when the
    externalization is complete, so it also measures the remaining work.
    """
    with config.open("rb") as handle:
        document = tomllib.load(handle)
    owned_prefixes = tuple(
        prefix
        for package in document.get("package", [])
        for prefix in package["owned_module_prefixes"]
    )
    declared: list[str] = [
        prefix
        for family in document.get("pending_family", [])
        for prefix in family["path_prefixes"]
    ] + [
        prefix
        for family in document.get("resident_family", [])
        for prefix in family["path_prefixes"]
    ]
    problems: list[str] = []
    for path in tracked_paths(repo_root):
        if path.suffix != ".lean" or not path.is_file():
            continue
        relative = path.relative_to(repo_root)
        if any(str(relative).startswith(prefix) for prefix in declared):
            continue
        module = module_name(lean_root, path)
        if module is not None and module.startswith(owned_prefixes):
            continue
        try:
            # The whole file, not a head window: a semantic module can carry a
            # delimited generated block far below its own preamble, which is exactly
            # how the Clebsch rank-three tables escaped this rule.
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        if BANNER_RE.search(text):
            problems.append(
                f"{relative}: generated source belonging to no package and to no"
                " declared pending family"
            )
    return sorted(set(problems))


def resolve_generator(
    repo_root: Path, lean_root: Path, source: Path, reference: str
) -> Path | None:
    """Find the file a generated source names as its generator, or None.

    A banner names its generator the way its author ran it, so the same repository
    holds repository-relative references, Lean-root-relative references, and bare
    basenames meaning "beside the family".  All three are resolved here; an
    unresolvable reference is not a violation, because a generated source may
    legitimately name a program that was never kept.
    """
    candidates = [repo_root / reference, lean_root / reference]
    parent = source.parent
    while True:
        candidates.append(parent / reference)
        if parent == repo_root:
            break
        parent = parent.parent
    for candidate in candidates:
        if candidate.is_file():
            return candidate.resolve()
    return None


def undeclared_generator_references(
    repo_root: Path, lean_root: Path, config: Path
) -> list[str]:
    """Reject a resident generator that no declaration admits.

    The rule above sees generated Lean sources only, and the scan roots cover `lean`
    and `papers` only, so a certificate family's generator — a Python or C++ program
    under `notes/` — is invisible to every other rule unless an adopted package
    already lists its basename or holds a byte-identical copy.  Neither applies while
    the family is still resident, which is exactly when the generator most needs to be
    declared: the ownership boundary moves the generator with the family it writes.
    """
    with config.open("rb") as handle:
        document = tomllib.load(handle)
    declared = [
        prefix
        for table in ("pending_family", "resident_family")
        for family in document.get(table, [])
        for prefix in family["path_prefixes"]
    ]
    # One line per undeclared generator, not per generated leaf: a single order-25
    # generator writes thousands of them, and a report that long hides every other
    # violation it is printed beside.
    consumers: dict[str, list[str]] = {}
    for path in tracked_paths(repo_root):
        if path.suffix != ".lean" or not path.is_file():
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        for reference in set(GENERATOR_RE.findall(text)):
            generator = resolve_generator(repo_root, lean_root, path, reference)
            if generator is None:
                continue
            try:
                relative = generator.relative_to(repo_root)
            except ValueError:
                continue
            if any(str(relative).startswith(prefix) for prefix in declared):
                continue
            consumers.setdefault(str(relative), []).append(
                str(path.relative_to(repo_root))
            )
    return [
        f"{generator}: generator of {len(sources)} generated source(s) including"
        f" {min(sources)}, declared by no pending or resident family"
        for generator, sources in sorted(consumers.items())
    ]


def copied_package_file_violations(
    repo_root: Path, config: Path, libraries_root: Path
) -> list[str]:
    """Reject a monorepo file that is byte-identical to a file an official package owns.

    A generator or generated leaf copied back under a different name defeats every
    name-based rule.  Content identity does not care what the copy is called.
    """
    with config.open("rb") as handle:
        document = tomllib.load(handle)
    pending_prefixes = [
        prefix
        for family in document.get("pending_family", [])
        for prefix in family["path_prefixes"]
    ]
    owned: dict[str, str] = {}
    for package in document.get("package", []):
        root = libraries_root / package["name"]
        manifest_path = root / "MANIFEST.json"
        if not manifest_path.is_file():
            continue
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        for source in manifest.get("sources", []):
            owned[source["sha256"]] = f"{package['name']}:{source['path']}"
        for script in sorted((root / "scripts").glob("**/*")):
            if script.is_file():
                owned[sha256(script)] = f"{package['name']}:{script.relative_to(root)}"
    problems: list[str] = []
    for path in tracked_paths(repo_root):
        if not path.is_file():
            continue
        relative = path.relative_to(repo_root)
        if any(str(relative).startswith(prefix) for prefix in pending_prefixes):
            continue
        digest = sha256(path)
        if digest in owned:
            problems.append(f"{relative}: byte-identical to {owned[digest]}")
    return sorted(set(problems))


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def official_library_violations(config: Path, libraries_root: Path) -> list[str]:
    with config.open("rb") as handle:
        document = tomllib.load(handle)
    problems: list[str] = []
    for package in document.get("package", []):
        root = libraries_root / package["name"]
        if not root.is_dir():
            problems.append(f"{root}: official library checkout is missing")
            continue
        head = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=root, check=True, text=True, capture_output=True
        ).stdout.strip()
        if head != package["commit"]:
            problems.append(f"{root}: HEAD {head} does not match pin {package['commit']}")
        manifest_path = root / "MANIFEST.json"
        if not manifest_path.is_file():
            problems.append(f"{manifest_path}: missing")
            continue
        if sha256(manifest_path) != package["manifest_sha256"]:
            problems.append(f"{manifest_path}: hash does not match the monorepo pin")
            continue
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        for source in manifest.get("sources", []):
            path = root / source["path"]
            if not path.is_file() or sha256(path) != source["sha256"]:
                problems.append(f"{path}: missing or differs from the sealed source")
        problems.extend(trust_fact_violations(package, root, config.parent))
    return sorted(set(problems))


def trust_fact_violations(package: dict, root: Path, trust_dir: Path) -> list[str]:
    """The monorepo's pinned fact must be the byte-identical artifact the package published."""
    relative = package.get("trust_fact")
    if relative is None:
        return [f"{package['name']}: pins no trust fact"]
    published = root / "TRUST_FACT.json"
    pinned = trust_dir / relative
    if not published.is_file():
        return [f"{published}: the package publishes no trust fact"]
    if not pinned.is_file():
        return [f"{pinned}: the pinned copy is missing"]
    if published.read_bytes() != pinned.read_bytes():
        return [f"{pinned}: differs from the package's published trust fact"]
    return []


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root", type=Path, default=REPO_ROOT)
    parser.add_argument("--lean-root", type=Path)
    parser.add_argument("--config", type=Path)
    parser.add_argument("--libraries-root", type=Path, default=Path.home() / "src/lean")
    parser.add_argument("--verify-official-libraries", action="store_true")
    args = parser.parse_args()
    repo_root = args.repo_root.resolve()
    lean_root = (args.lean_root or repo_root / "lean").resolve()
    config = (args.config or lean_root / "trust/certificate-packages.toml").resolve()
    problems = violations(repo_root, lean_root, config)
    problems.extend(undeclared_generated_families(repo_root, lean_root, config))
    problems.extend(undeclared_generator_references(repo_root, lean_root, config))
    if args.verify_official_libraries:
        libraries_root = args.libraries_root.resolve()
        problems.extend(official_library_violations(config, libraries_root))
        problems.extend(
            copied_package_file_violations(repo_root, config, libraries_root)
        )
    if problems:
        print("certificate boundary violations:")
        for problem in problems:
            print(f"- {problem}")
        return 1
    print("certificate boundary ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
